mapper.select:
SELECT
entrance_id as entranceId,
(INOCTETS_SPEED+OUTOCTETS_SPEED) as sum,
RECV_TIME as reportTime
FROM
traffic_netflow_port_info 		

	
		AND RECV_TIME >= #{searchReportStartTime}
	
	
		AND  RECV_TIME < #{searchReportEndTime}
				

order by recv_time asc;

SELECT report.service,report.report_time,report.sum,dic.service_name_zh,dic.service_name_zh,dic.service_name_ru from ( SELECT service,report_time,sum(sum) as sum FROM ntc_service_report
AND service in (${searchService})
AND report_time >= #{searchReportStartTime}
AND report_time < #{searchReportEndTime}
GROUP BY service, report_time order by report_time ASC) report LEFT JOIN ntc_service_dic dic on report.service = dic.service_code

SELECT
 sum(reject_num+drop_conn_num) as sum
FROM
ntc_total_report
			
	
		AND report_time >= #{searchReportStartTime}
	
	
		AND report_time < #{searchReportEndTime}

SELECT 	(reject_num+drop_conn_num) as sum,
report_time as reportTime
FROM
ntc_total_report

	
		AND report_time >= #{searchReportStartTime}
	
	
		AND report_time < #{searchReportEndTime}
	

order by report_time
asc;
